package org.apache.commons.math3.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_reciprocal_TriageGen3Test {

    private static final double EPSILON = 1.0e-15;

    @Test
    public void testReciprocal_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.reciprocal();
        assertEquals(Complex.NaN, result);
    }

    @Test
    public void testReciprocal_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.reciprocal();
        assertEquals(Complex.NaN, result);
    }

    @Test
    public void testReciprocal_Infinite() {
        // Test infinite real part
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        assertEquals(Complex.ZERO, c1.reciprocal());

        // Test infinite imaginary part
        Complex c2 = new Complex(0.0, Double.NEGATIVE_INFINITY);
        assertEquals(Complex.ZERO, c2.reciprocal());
    }

    @Test
    public void testReciprocal_RealDominant() {
        // |real| >= |imaginary|
        // q = imaginary / real = 0.5 / 2.0 = 0.25
        // scale = 1 / (0.5 * 0.25 + 2.0) = 1 / (0.125 + 2.0) = 1 / 2.125 = 0.47058823529411764
        // realPart = scale = 0.47058823529411764
        // imagPart = -scale * q = -0.47058823529411764 * 0.25 = -0.11764705882352941
        Complex c = new Complex(2.0, 0.5);
        Complex result = c.reciprocal();

        assertEquals(0.47058823529411764, result.getReal(), EPSILON);
        assertEquals(-0.11764705882352941, result.getImaginary(), EPSILON);
    }

    @Test
    public void testReciprocal_ImaginaryDominant() {
        // |real| < |imaginary|
        // q = real / imaginary = 1.0 / 4.0 = 0.25
        // scale = 1 / (1.0 * 0.25 + 4.0) = 1 / 4.25 = 0.23529411764705882
        // realPart = scale * q = 0.23529411764705882 * 0.25 = 0.058823529411764705
        // imagPart = -scale = -0.23529411764705882
        Complex c = new Complex(1.0, 4.0);
        Complex result = c.reciprocal();

        assertEquals(0.058823529411764705, result.getReal(), EPSILON);
        assertEquals(-0.23529411764705882, result.getImaginary(), EPSILON);
    }

    @Test
    public void testReciprocal_NegativeValues() {
        // Testing negative paths for branching
        // |real| (2.0) >= |imaginary| (1.0)
        Complex c = new Complex(-2.0, -1.0);
        Complex result = c.reciprocal();

        // 1 / (-2 - i) = (-2 + i) / ((-2)^2 + (-1)^2) = (-2 + i) / 5 = -0.4 + 0.2i
        // Wait, the formula in code:
        // q = -1 / -2 = 0.5
        // scale = 1 / (-1 * 0.5 + -2) = 1 / -2.5 = -0.4
        // realPart = scale = -0.4
        // imagPart = -scale * q = -(-0.4) * 0.5 = 0.2
        assertEquals(-0.4, result.getReal(), EPSILON);
        assertEquals(0.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testReciprocal_EqualityWithDivide() {
        // Verification against standard division logic
        Complex c = new Complex(3.0, 4.0);
        Complex result = c.reciprocal();
        Complex expected = new Complex(1.0, 0.0).divide(c);

        assertEquals(expected.getReal(), result.getReal(), EPSILON);
        assertEquals(expected.getImaginary(), result.getImaginary(), EPSILON);
    }
}
